import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        StringBuilder transformed = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            if (i + 2 < s.length() && s.charAt(i) == 'd' && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't') {
                transformed.append('.');
                i += 3;
            } else if (i + 1 < s.length() && s.charAt(i) == 'a' && s.charAt(i + 1) == 't') {
                transformed.append('@');
                i += 2;
            } else {
                transformed.append(s.charAt(i));
                i++;
            }
        }

        String finalStr = "";
        if (transformed.length() > 0) {
            char firstChar = transformed.charAt(0);
            if (firstChar == '.') {
                finalStr += "dot";
            } else if (firstChar == '@') {
                finalStr += "at";
            } else {
                finalStr += firstChar;
            }

            int at_marker = 0;
            for (int k = 1; k < transformed.length() - 1; k++) {
                char c = transformed.charAt(k);
                if (c == '@' && at_marker == 0) {
                    finalStr += c;
                    at_marker = 1;
                } else if (c == '@' && at_marker == 1) {
                    finalStr += "at";
                } else {
                    finalStr += c;
                }
            }

            char lastChar = transformed.charAt(transformed.length() - 1);
            if (lastChar == '.') {
                finalStr += "dot";
            } else if (lastChar == '@') {
                finalStr += "at";
            } else {
                finalStr += lastChar;
            }
        }
        System.out.println(finalStr);
        sc.close();
    }
}
